const form=document.querySelector('#settings'),feedback=document.querySelector('#feedback'),status=document.querySelector('#status');let saved=false;
async function request(url,data){const r=await fetch(url,{cache:'no-store',...(data!==undefined?{method:'POST',headers:{'Content-Type':'application/json','X-Solo-Local':'1'},body:JSON.stringify(data)}:{})});const result=await r.json();if(!r.ok)throw Error(result.error||'请求失败');return result}
function display(c){saved=c.hasKey;status.textContent=(c.hasKey?'密钥已配置':'尚未配置密钥')+' · '+c.model;document.querySelector('#model').value=c.model;document.querySelector('#key').placeholder=c.hasKey?'已保存，留空不更改':'填写你的 DeepSeek API Key'}
async function run(fn){form.querySelectorAll('button').forEach(b=>b.disabled=true);feedback.className='';feedback.textContent='正在处理…';try{await fn()}catch(e){feedback.className='admin-error';feedback.textContent=e.message}finally{form.querySelectorAll('button').forEach(b=>b.disabled=false)}}
form.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const apiKey=document.querySelector('#key').value.trim();display(await request('/api/settings',{model:document.querySelector('#model').value.trim(),apiKey}));document.querySelector('#key').value='';feedback.textContent='配置已保存在本机。可以测试连接，然后返回游戏。'})});
document.querySelector('#test').onclick=()=>run(async()=>{if(!saved)throw Error('请先填写密钥并保存配置。');if(document.querySelector('#key').value)throw Error('有尚未保存的密钥，请先保存配置。');feedback.textContent='正在请求 DeepSeek，最多等待 60 秒…';const r=await request('/api/test-connection',{});feedback.textContent=r.message});
document.querySelector('#clear').onclick=()=>run(async()=>{display(await request('/api/settings',{model:document.querySelector('#model').value.trim(),clearKey:true}));document.querySelector('#key').value='';feedback.textContent='本地密钥已清除。'});
request('/api/settings').then(display).catch(e=>{status.textContent=e.message;status.classList.add('admin-error')});
